fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    // Ensure the replacement array is non-empty (as specified in the problem)
    assert!(!values.is_empty(), "Replacement array must be non-empty");
    
    // Ensure the input and mask arrays have the same length
    assert_eq!(a.len(), mask.len(), "Input array and mask must have the same length");
    
    let values_len = values.len();
    
    // Create the result vector by iterating through the input
    a.into_iter()
        .zip(mask.into_iter())
        .enumerate()
        .map(|(i, (a_val, mask_val))| {
            if mask_val {
                // Use i modulo values_len to get the replacement index
                let replacement_index = i % values_len;
                values[replacement_index]
            } else {
                a_val
            }
        })
        .collect()
}